import { helperNames } from '../../helperNames';
import { modifyHTML } from '../../htmlShell';
import { noticeText } from '../../mixedContentNotices';
import { setDocumentShells } from '../../rewriteHTML';
import {
	SW_PORT,
	TRANSPORT_INIT,
	WORKER_MODULES,
} from '../../transport/messages';
import { listenOn, messageOf, startPort } from '../../transport/ports';
import { accessFailureParts } from '../accessFailureParts';
import { accessFailures } from '../accessFailures';
import { socketStandIns } from '../bareClient';
import { cacheCallParts } from '../cacheCallParts';
import { cacheCalls } from '../cacheCalls';
import { messageField, readModules, type HandedModules } from '../Client';
import { recordSize } from '../idbSize';
import { idbSizeParts } from '../idbSizeParts';
import { partitionLegacyFileSystem } from '../legacyFileSystem';
import { legacyFileSystemParts } from '../legacyFileSystemParts';
import { mixedContentParts } from '../mixedContentParts';
import { originFrom } from '../originFrom';
import { originFromParts } from '../originFromParts';
import { reportParts } from '../reportParts';
import { reportsSeen } from '../reportsSeen';
import { handModules } from '../rewriter';
import { socketParts } from '../socketParts';
import { bucketMethods } from '../storageBucketMethods';
import { storageBucketParts } from '../storageBucketParts';
import { storageUsage } from '../storageUsage';
import { carry as carryWebTransport } from '../webTransport';
import { webTransportParts } from '../webTransportParts';
import { standIn as webTransportStandIn } from '../webTransportStandIn';
import { workerStart } from '../workerStart';
import { workerStartParts } from '../workerStartParts';
import WorkerClient, {
	setServiceWorkerPort,
	setWorkerModules,
	setWorkerTransportPort,
} from './Client';
import createWorkerClient from './worker';

// a worker's WebTransport stand-in and what carries its sessions are the
// bundle's own code
webTransportParts.standIn = () => webTransportStandIn;
// and so is the sizing of an IndexedDB record (../idbSizeParts.ts)
idbSizeParts.recordSize = () => recordSize;
idbSizeParts.storageUsage = () => storageUsage;
// and the methods behind navigator.storageBuckets' hooks
storageBucketParts.methods = () => bucketMethods;
// and the per-site legacy file system (../legacyFileSystemParts.ts)
legacyFileSystemParts.partition = () => partitionLegacyFileSystem;
// and the text of a mixed content notice (../mixedContentParts.ts)
mixedContentParts.noticeText = () => noticeText;
// and what a page's add(), addAll() and caches.match() do (../cacheCallParts.ts)
cacheCallParts.calls = () => cacheCalls;
// and what Origin.from() answers (../originFromParts.ts)
originFromParts.answer = () => originFrom;
// and the wording of the access API's errors (../accessFailureParts.ts)
accessFailureParts.failures = () => accessFailures;
// and the un-routing of ReportingObserver's reports (../reportParts.ts)
reportParts.seen = () => reportsSeen;
// and what a worker's construction does past its checks (../workerStartParts.ts)
workerStartParts.start = () => workerStart;
// and what a WebSocket stand-in does (../socketParts.ts)
socketParts.standIns = () => socketStandIns;
// and the HTML shell of a data: document it routes (a worker routes no XML
// one: it goes as it is)
setDocumentShells((name) => (name === 'modifyHTML' ? modifyHTML : undefined));
/** set once the bootstrap came without a transport (its creator found none to hand it): nothing carries its sessions */
let transportless = false;
webTransportParts.carry = () =>
	transportless
		? () => Promise.reject(new Error('no transport'))
		: carryWebTransport;

/**
 * The transport port a TRANSPORT_INIT the browser delivered carries, read
 * with its own getters (src/transport/ports.ts): a shared worker's script
 * may have replaced them, or dispatch a message of its own, by the time a
 * later page connects
 */
const transportOf = (event: Event) => {
	const message = messageOf(event);
	return message &&
		typeof message.data === 'object' &&
		message.data !== null &&
		TRANSPORT_INIT in message.data
		? (message.ports[0] ?? null)
		: null;
};

const shared =
	typeof SharedWorkerGlobalScope !== 'undefined' &&
	globalThis instanceof SharedWorkerGlobalScope;

// taken when the bundle loads, before the worker's own script: a message's
// ports as the browser made them (its data is read the same way,
// messageField)
const messagePorts = Reflect.getOwnPropertyDescriptor(
	MessageEvent.prototype,
	'ports',
)?.get;
const portsOf = (event: MessageEvent): readonly MessagePort[] =>
	messagePorts
		? (Reflect.apply(messagePorts, event, []) as readonly MessagePort[])
		: event.ports;
const portListen = MessagePort.prototype.addEventListener;
const portStart = MessagePort.prototype.start;
const portClose = MessagePort.prototype.close;

/**
 * A dedicated worker's first message, from the context that started it
 * (Client.provisionWorkerTransport): its transport port, and with
 * `rewriter: 'wasm'` the compiled modules that context holds, or a port
 * they follow on when they had not reached it yet (WORKER_MODULES). Only
 * the browser's own event is taken: one the worker's script dispatches at
 * itself would otherwise choose the worker's transport and the module that
 * rewrites what it evaluates.
 */
let takeBootstrap: ((event: MessageEvent) => boolean) | undefined;

// The page that constructed this worker posts a transport port before any of
// the worker's own code runs (see Client.provisionWorkerTransport). Listen
// first so the message never reaches the worker's own handlers.
setWorkerTransportPort(
	new Promise<MessagePort>((resolve) => {
		if (shared) {
			// every connecting page offers a port; the first one is used and
			// every offer is kept from the worker's own handlers
			listenOn(globalThis, 'connect', (event) => {
				const port = messageOf(event)?.ports[0];
				if (!port) return;
				listenOn(port, 'message', (message) => {
					const transport = transportOf(message);
					if (!transport) return;
					message.stopImmediatePropagation();
					resolve(transport);
				});
				startPort(port);
			});
			return;
		}

		setWorkerModules(
			new Promise<HandedModules | null>((given) => {
				const give = (modules: HandedModules | null) => {
					// this realm's library rewrites with them from now on, in
					// this task: what the page's next handler evaluates is
					// the module's
					if (modules) handModules(modules);
					given(modules);
				};
				takeBootstrap = (event) => {
					if (!event.isTrusted) return false;
					const transport = messageField(event, TRANSPORT_INIT) !== undefined;
					const field = messageField(event, WORKER_MODULES);
					if (!transport && field === undefined) return false;
					takeBootstrap = undefined;
					removeEventListener('message', handler);
					const ports = portsOf(event);
					// (a worker whose creator found no transport to hand it:
					// its port never comes, and its WebTransport sessions fail
					// as the stand-in alone fails them)
					if (transport) resolve(ports[0]);
					else transportless = true;
					// the modules follow on the message's last port
					const later =
						field === true && ports.length > (transport ? 1 : 0)
							? ports[ports.length - 1]
							: undefined;
					if (!later) {
						give(readModules(event, WORKER_MODULES));
						return true;
					}
					Reflect.apply(portListen, later, [
						'message',
						(message: MessageEvent) => {
							if (!message.isTrusted) return;
							give(readModules(message, WORKER_MODULES));
							Reflect.apply(portClose, later, []);
						},
					]);
					Reflect.apply(portStart, later, []);
					return true;
				};
			}),
		);

		const handler = (event: MessageEvent) => {
			if (takeBootstrap?.(event)) event.stopImmediatePropagation();
		};

		addEventListener('message', handler);
	}),
);

// An emulated service worker's controller posts its port to STomp's service
// worker right after the transport's (docs/service-workers.md); kept from
// the worker's own handlers the same way. Only a dedicated worker gets one.
if (
	typeof SharedWorkerGlobalScope === 'undefined' ||
	!(globalThis instanceof SharedWorkerGlobalScope)
)
	setServiceWorkerPort(
		new Promise<MessagePort>((resolve) => {
			// only one the browser delivered (or STomp's replay of one, a
			// module worker's held events), read with its own getters
			const handler = (event: MessageEvent) => {
				const message = messageOf(event);
				if (
					!message ||
					typeof message.data !== 'object' ||
					message.data === null ||
					!(SW_PORT in message.data) ||
					!message.ports[0]
				)
					return;
				event.stopImmediatePropagation();
				removeEventListener('message', handler);
				resolve(message.ports[0]);
			};
			addEventListener('message', handler);
		}),
	);

// Classic-script global consumed (and deleted) by the inject snippet in
// rewriteJS.ts. See ../dom/entry.ts. A module worker's preamble hands over
// the events it held while it loaded this bundle.
Reflect.defineProperty(globalThis, 'createClient', {
	value: (
		config: Parameters<typeof createWorkerClient>[0],
		codecKey: string,
		held?: MessageEvent[],
	) => {
		// the first message may be among those a module worker's preamble
		// held while it loaded this bundle: taken now, so the modules it
		// brought rewrite what the page's module evaluates from its first
		// statement, and never dispatched again
		if (held && takeBootstrap) {
			const index = own$findIndex(held, (event) => takeBootstrap?.(event));
			if (index !== -1) own$splice(held, index, 1);
		}
		createWorkerClient(config, codecKey);
		(
			Reflect.get(globalThis, helperNames(config).client) as WorkerClient
		).releaseHeld(held);
	},
	configurable: true,
	writable: true,
});
